				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$Z=\left\{\genfrac{}{}{0pt}{}{\frac{{[\frac{y}{M\left(x\right)}]}^{L\left(x\right)}-1}{S\left(x\right)L\left(x\right)} ;\quad L(x) \ne 0}{\begin{array}{l} \\ \\ \frac{\mathrm{ln}[\frac{y}{M\left(x\right)}]}{S\left(x\right)} ;\quad L(x) = 0\end{array}}\right..$$\end{document}Z=[yMx]Lx-1SxLx;L(x)≠0ln[yMx]Sx;L(x)=0.
